create table RB_AUTO_TRAN_INFO (SEQ_NO VARCHAR(50) not null  ,INTERNAL_KEY INT null  ,CLIENT_NO VARCHAR(22) not null  ,BASE_ACCT_NO VARCHAR(50) null  ,PROD_TYPE VARCHAR(20) null  ,CCY VARCHAR(3) null  ,ACCT_SEQ_NO VARCHAR(5) null  ,PRINCIPAL_AMT DECIMAL(17,2) null  ,REGISTER_DATE TIMESTAMP(3) null  ,MATURITY_DATE TIMESTAMP(3) null  ,FUND_FROM_ACCT_NO VARCHAR(50) null  ,FUND_FROM_NAME VARCHAR(100) null  ,FUND_FROM_BANK_NO VARCHAR(12) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,CREATE_TIMESTAMP VARCHAR(26) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  ,COMPANY VARCHAR(20) null  , primary key(SEQ_NO,CLIENT_NO));